-- Initial public register records. All entries are fictional scenario content for the portal.
insert into public.career_listings (title,department,summary,description,requirements,location,openings,status)
select v.title,v.department,v.summary,v.description,v.requirements,v.location,v.openings,'open'
from (values
('Diplomatic Affairs Officer','Global Affairs Canada','Support bilateral engagement, country files and diplomatic correspondence.','Prepare briefing notes, maintain country records and support diplomatic meetings.','Strong written communication, reliable activity and respectful conduct.','Remote / Diplomatic missions',3),
('Consular Services Assistant','Consular Services','Help organise citizen service requests and document records.','Assist with application triage, status updates and service desk organisation.','Attention to detail, discretion and consistent availability.','Remote',2),
('Treaty and Agreements Researcher','Policy and Treaties Directorate','Maintain treaty records and research bilateral agreements.','Organise agreement records, summaries and public register information.','Research skills, clear writing and familiarity with the portal.','Remote',2),
('Diplomatic Mission Liaison','International Relations Directorate','Coordinate mission updates and public-facing country information.','Support mission communications, event scheduling and briefing updates.','Professional communication and collaborative working style.','Diplomatic missions',2)
) as v(title,department,summary,description,requirements,location,openings)
where not exists (select 1 from public.career_listings c where lower(c.title)=lower(v.title));

insert into public.treaties (country,title,category,signed_on,status,summary,body,published)
select v.country,v.title,v.category,v.signed_on::date,v.status,v.summary,v.body,true
from (values
('Dominican Republic','Cultural Cooperation Framework','Framework','2026-05-12','active','Establishes a framework for cultural exchanges and public diplomacy.','Article I — Purpose: The parties will encourage cultural exchange, educational dialogue and public diplomacy.' || chr(10) || chr(10) || 'Article II — Cooperation: Designated representatives may propose joint programmes and exchange public information.' || chr(10) || chr(10) || 'Article III — Review: The framework may be reviewed by mutual agreement.'),
('Falkland Islands','Maritime Communication Protocol','Protocol','2026-04-18','active','Provides a channel for maritime communication and administrative consultation.','Article I — Communication: Designated offices may exchange routine maritime notices.' || chr(10) || chr(10) || 'Article II — Coordination: Each party will identify a liaison contact.' || chr(10) || chr(10) || 'Article III — Review: Implementation is reviewed periodically.'),
('Finland','Northern Cooperation Accord','Agreement','2026-06-01','active','Sets out cooperation on education, innovation and northern affairs.','Article I — Cooperation: The parties may coordinate on education, innovation and northern affairs.' || chr(10) || chr(10) || 'Article II — Exchanges: Officials may arrange reciprocal visits and share public research.' || chr(10) || chr(10) || 'Article III — Entry into effect: This accord takes effect on signature and may be amended by mutual written agreement.'),
('Germany','Bilateral Consultation Agreement','Agreement','2026-03-20','active','Establishes regular consultation between designated foreign affairs representatives.','Article I — Consultations: Representatives will seek to hold regular bilateral consultations.' || chr(10) || chr(10) || 'Article II — Working groups: The parties may establish working groups for agreed policy topics.' || chr(10) || chr(10) || 'Article III — Amendments: This agreement may be amended by written mutual consent.'),
('Ireland','Dialogue Framework','Framework','2026-02-14','suspended','Provides a formal channel for dialogue; current engagement is suspended in the register.','Article I — Dialogue: The parties may use designated representatives to exchange views.' || chr(10) || chr(10) || 'Article II — Suspension: Formal activities under this framework are recorded as suspended pending further review.' || chr(10) || chr(10) || 'Article III — Resumption: Engagement may resume following a recorded review decision.'),
('Lebanon','Consular Coordination Note','Memorandum','2026-01-30','active','Records administrative coordination on consular case handling and public notices.','Section I — Coordination: Designated offices may coordinate administrative case handling.' || chr(10) || chr(10) || 'Section II — Public information: Each office may share public notices and service updates.' || chr(10) || chr(10) || 'Section III — Review: The note may be reviewed at any time by designated representatives.'),
('Northern Ireland','Community Liaison Protocol','Protocol','2026-02-25','suspended','Records a public liaison channel for community and administrative engagement.','Article I — Liaison: Designated representatives may maintain a public liaison channel.' || chr(10) || chr(10) || 'Article II — Current status: Activities under this protocol are currently suspended in the register.' || chr(10) || chr(10) || 'Article III — Review: Status is subject to future administrative review.'),
('Ukraine','Emergency Coordination Framework','Framework','2026-04-02','active','Provides an administrative framework for exchanging public emergency coordination information.','Article I — Information exchange: Designated offices may exchange public emergency coordination information.' || chr(10) || chr(10) || 'Article II — Liaison: A liaison contact may be designated by each party.' || chr(10) || chr(10) || 'Article III — Review: The framework is reviewed as operational needs change.'),
('United States','Bilateral Consultation Agreement','Agreement','2026-05-05','active','Establishes regular consultation on agreed bilateral topics.','Article I — Consultations: The parties may arrange bilateral consultations on agreed topics.' || chr(10) || chr(10) || 'Article II — Records: Meeting summaries may be maintained by the designated offices.' || chr(10) || chr(10) || 'Article III — Amendments: The agreement may be amended by mutual written consent.')
) as v(country,title,category,signed_on,status,summary,body)
where not exists (select 1 from public.treaties t where lower(t.country)=lower(v.country) and lower(t.title)=lower(v.title));

insert into public.active_operations (title,country,category,status,summary,public_details,published)
select v.title,v.country,v.category,v.status,v.summary,v.details,true
from (values
('Northern Cooperation Mission','Finland','diplomatic_mission','active','Coordinates public diplomacy and bilateral programme updates.','The mission maintains public programme records, scheduled consultations and routine liaison updates.'),
('Consular Coordination Mission','Lebanon','humanitarian','active','Coordinates service notices and administrative liaison.','Public-facing activities focus on service coordination, information sharing and casework administration.'),
('Regional Security Monitoring','Ukraine','conflict','suspended','Maintains a public register entry for regional security monitoring.','Operational details are restricted to approved public summaries; status is currently suspended.')
) as v(title,country,category,status,summary,details)
where not exists (select 1 from public.active_operations o where lower(o.title)=lower(v.title));

insert into public.site_updates (title,department,summary,body,published,published_at)
select 'Government services directory updated','Global Affairs Canada','The services directory now includes passport requests, visa applications, diplomatic careers and an updated document register.','The public services directory has been updated. Visitors can submit service requests, save confirmation numbers, browse government documents and view current diplomatic register entries.',true,now()
where not exists (select 1 from public.site_updates where title='Government services directory updated');